import './direct-editing.css';
import {MixerPanel,SoundPanel} from './mixer-panel';
import {Startup} from './startup';
import VoiceDirection from './voice-direction';
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { ArrowDownToLine, ArrowLeft, ArrowRight, Check, CheckCheck, ChevronDown, Clapperboard, Command, Copy, ExternalLink, FileJson, Film, FolderOpen, Hash, Keyboard, Layers3, Link, LoaderCircle, Mic, Music2, Plus, RefreshCw, Save, Scissors, Settings2, ShieldCheck, Sparkles, Captions, Type, Terminal, Trash2, Upload, WandSparkles, X } from 'lucide-react';
import { Button, Empty, Field, Library, Modal, Player, Storyboard, Timeline } from './components';
import { bytes, coverage, createClock, request, sortedScenes, timelineDuration, timecode } from './model';
import { OverlayEditor } from './overlays';
import { isHosted } from './engine';
import {ClipFields,EditTools,controlKeys} from './clip-inspector';
import {useEditorTools} from './webmcp';
import ProjectBrowser from './projects';
import ProjectLauncher from './project-launcher';
import ImageGenerator from './image-generator';

const kindNames = { video: '映像', audio: '音声', image: '画像' };
const decisionNames = { pending: '未判定', accepted: '採用', rejected: '不採用' };
const jobNames = { queued: '待機中', running: '実行中', completed: '完了', failed: '失敗', awaiting_import: '音声の取り込み待ち' };
const formObject = form => Object.fromEntries(new FormData(form));
const numeric = (data, keys) => { keys.forEach(key => { if (key in data) data[key] = Number(data[key]); }); return data; };

function SceneSelect({ scenes, value, onChange, name = 'sceneId', defaultValue = '', required = false }) {
  return <select aria-label="シーン" data-action="scene.choose" name={name} {...(onChange ? { value, onChange } : { defaultValue })} required={required}><option value="">シーン未割り当て</option>{scenes.map(scene => <option key={scene.id} value={scene.id}>{String(scene.order + 1).padStart(2, '0')} · {scene.title}</option>)}</select>;
}

function ResultPanel({ result, title = '実行結果' }) {
  if (result == null) return null;
  const urls = [];
  const collect = (value, key = '') => {
    if (value && typeof value === 'object' && value.name && typeof value.url === 'string' && (value.url.startsWith('/api/download?')||value.url.startsWith('http://127.0.0.1:4318/api/download?')) && !urls.some(item => item.url === value.url)) urls.push({ url: value.url, label: value.name });
    if (typeof value === 'string' && (value.startsWith('/api/download?')||value.startsWith('http://127.0.0.1:4318/api/download?'))) { if (!urls.some(item => item.url === value)) urls.push({ url: value, label: key === 'textUrl' ? 'ナレーション原稿' : key === 'url' ? 'ファイルをダウンロード' : key }); }
    else if (Array.isArray(value)) value.forEach(item => collect(item, key));
    else if (value && typeof value === 'object') Object.entries(value).forEach(([k, v]) => collect(v, k));
  };
  collect(result);
  return <section className="result-panel"><strong>{title}</strong>{(result.taggedScript||result.script) && <pre className="script-result">{result.taggedScript||result.script}</pre>}{result.stylePrompt&&<pre className="script-result">{result.stylePrompt}</pre>}{urls.length > 0 && <div className="download-links">{urls.map(item => <a href={item.url} key={item.url} download data-action="result.download"><ArrowDownToLine size={14} />{item.label}</a>)}</div>}{result.warnings?.length > 0 && <ul className="result-warnings">{result.warnings.map((warning, i) => <li key={i}>{warning}</li>)}</ul>}{result.note && <p>{result.note}</p>}<details><summary>詳細と保存先</summary><pre>{JSON.stringify(result, null, 2)}</pre></details></section>;
}

function GenerationPanel({ state, run, busy, selectedScene }) {
  const [result, setResult] = useState(null);
  const [provider,setProvider]=useState('codex');
  const [workflowText, setWorkflowText] = useState('');
  const workflowUploadRef = useRef(null);
  const [presets, setPresets] = useState([]), [presetId, setPresetId] = useState(''), [generationKind, setGenerationKind] = useState('video');
  useEffect(() => { let alive = true; request('/api/workflows').then(value => { if (alive) setPresets(value.presets || []); }).catch(() => {}); return () => { alive = false; }; }, []);
  const submit = async event => {
    event.preventDefault();
    const data = formObject(event.currentTarget);
    let workflow;
    try { workflow = JSON.parse(data.workflow); } catch { setResult({ error: 'ワークフローJSONを読み取れません。「API形式」で保存したJSONを貼り付けてください。' }); return; }
    if (!workflow || typeof workflow !== 'object' || Array.isArray(workflow)) { setResult({ error: 'ワークフローはJSONオブジェクトで指定してください。' }); return; }
    const response = await run('generation.submit', { kind: data.kind, prompt: data.prompt, workflow, sceneId: data.sceneId || null, ...(data.seed ? { seed: Number(data.seed) } : {}) });
    if (response) setResult(response.result);
  };
  const providerSelect=<Field label="生成サービス"><select value={provider} onChange={e=>setProvider(e.target.value)}><option value="codex">GPT Image</option><option value="comfy">ComfyUI</option></select></Field>;
  if(provider==='codex')return <>{providerSelect}<ImageGenerator state={state} run={run} busy={busy} selectedScene={selectedScene}/></>;
  return <>{providerSelect}<div className="inspector-intro"><h3>ComfyUI</h3></div><form className="panel-form" onSubmit={submit}>{presets.length > 0 && <Field label="ワークフロー"><select value={presetId} data-action="generation.preset" onChange={event => { const id = event.target.value; setPresetId(id); const preset = presets.find(item => item.id === id); if (preset) { setWorkflowText(JSON.stringify(preset.workflow, null, 2)); setGenerationKind(preset.kind); } }}><option value="">カスタム</option>{presets.map(preset => <option key={preset.id} value={preset.id}>{preset.name}</option>)}</select>{presetId && <small>{presets.find(preset => preset.id === presetId)?.note}</small>}</Field>}<div className="field-row"><Field label="素材の種類"><select name="kind" value={generationKind} onChange={event => setGenerationKind(event.target.value)} data-action="generation.kind"><option value="video">映像</option><option value="audio">音声</option><option value="image">画像</option></select></Field><Field label="シード値"><input name="seed" type="number" min="0" placeholder="自動" data-action="generation.seed" /></Field></div><Field label="割り当て先"><SceneSelect key={selectedScene || 'empty'} scenes={sortedScenes(state.storyboard)} defaultValue={selectedScene || ''} /></Field><Field label="生成プロンプト"><textarea name="prompt" rows="4" required placeholder="夕方の教室。窓から柔らかい光、ゆっくりと寄るカメラ…" data-action="generation.prompt" /></Field><Field label="ComfyUIワークフロー（API形式）" hint="文字列中の {{prompt}} と {{seed}} を置き換えます。ComfyUI側でモデルと保存ノードを設定してください。"><textarea className="code-input" name="workflow" value={workflowText} onChange={event => setWorkflowText(event.target.value)} rows="8" required placeholder={'{\n  "6": {\n    "class_type": "CLIPTextEncode",\n    "inputs": { "text": "{{prompt}}" }\n  }\n}'} data-action="generation.workflow" /></Field><input ref={workflowUploadRef} type="file" accept="application/json,.json" className="visually-hidden" aria-label="ComfyUI APIワークフローJSON" data-action="generation.workflow.file" onChange={async event => { const file = event.target.files?.[0]; if (!file) return; try { const source = await file.text(); JSON.parse(source); setWorkflowText(source); setResult(null); } catch { setResult({ error: 'JSONファイルを読み取れません。ComfyUIのAPI形式で書き出したファイルを選択してください。' }); } event.target.value = ''; }} /><div className="button-row"><Button icon={FolderOpen} action="generation.workflow.open" onClick={() => workflowUploadRef.current.click()}>JSONを読み込む</Button><a className="button" href={/^https?:\/\//.test(state.settings.comfyUrl) ? state.settings.comfyUrl : 'http://127.0.0.1:8188'} target="_blank" rel="noreferrer" data-action="generation.openComfy"><ExternalLink size={13} />ComfyUIを開く</a></div><div className="inline-note"><ShieldCheck size={14} />生成結果は新規素材として保存されます。</div><button type="submit" className="button primary full-width" data-action="generation.submit" disabled={busy}>{busy === 'generation.submit' ? <LoaderCircle className="spin" size={14} /> : <Sparkles size={14} />}ComfyUIで生成</button></form>{result?.error ? <p className="inline-error">{result.error}</p> : <ResultPanel result={result} title="生成ジョブ" />}<Jobs jobs={state.jobs.filter(j => j.type === 'generation')} run={run} busy={busy} /></>;
}

function Jobs({ jobs, run, busy, narration = false, onImport }) {
  if (!jobs.length) return null;
  return <div className="job-list"><div className="inspector-section-title">最近のジョブ <span>{jobs.length}</span></div>{[...jobs].reverse().slice(0, 10).map(job => <article className="job" key={job.id}><div><span className={`job-dot ${job.status}`} /><strong>{jobNames[job.status] || job.status}</strong><small>{new Date(job.createdAt).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' })}</small></div><p>{job.prompt}</p>{job.error && <span className="inline-error">{job.error}</span>}{narration ? <>{job.result?.script && <details><summary>原稿と引き渡しファイル</summary><ResultPanel result={job.result} title="Google Vidsへの引き渡し" /></details>}{job.status === 'awaiting_import' && <Button icon={Upload} action="narration.import.open" entity={job.id} onClick={() => onImport(job)}>完成した音声を取り込む</Button>}</> : !['completed', 'failed'].includes(job.status) && <Button icon={RefreshCw} action="generation.refresh" entity={job.id} disabled={!!busy} onClick={() => run('generation.refresh', { id: job.id })}>生成結果を確認</Button>}</article>)}</div>;
}

function NarrationPanel({ state, run, busy, selectedScene, onImport, onToast }) {
  const [mode, setMode] = useState('codex'), [result, setResult] = useState(null);
  const vidsUrl = /^https:\/\//i.test(state.settings.vidsUrl || '') ? state.settings.vidsUrl : 'https://docs.google.com/videos/';
  const submit = async event => { event.preventDefault(); const data = formObject(event.currentTarget); const response = await run('narration.prepare', { ...data, mode, sceneId: data.sceneId || null }); if (response) setResult(response.result); };
  return <><div className="inspector-intro"><h3>ナレーション</h3></div><div className="handoff-steps"><span className="active">1 原稿を作る</span><ArrowRight size={11} /><span>2 Vidsで生成</span><ArrowRight size={11} /><span>3 取り込む</span></div><form className="panel-form" onSubmit={submit}><Field label="原稿の作り方"><select value={mode} data-action="narration.mode" onChange={event => setMode(event.target.value)}><option value="codex">Codex App Serverで原稿を生成</option><option value="local">入力した文章をそのまま使用</option></select></Field><Field label="割り当て先"><SceneSelect key={selectedScene || 'empty'} scenes={sortedScenes(state.storyboard)} defaultValue={selectedScene || ''} /></Field><Field label={mode === 'codex' ? 'ナレーションへの指示' : 'ナレーション原稿'}><textarea name="prompt" rows="5" required data-action="narration.prompt" placeholder={mode === 'codex' ? '高校生向けの英語講座の導入。明るく落ち着いた口調で、15秒の原稿を書いて。' : '読み上げたい文章を入力してください。'} /></Field><div className="field-row"><Field label="言語"><select name="language" data-action="narration.language"><option value="ja-JP">日本語</option><option value="en-US">English (US)</option><option value="en-GB">English (UK)</option></select></Field><Field label="声の希望"><input name="voice" placeholder="落ち着いた声" data-action="narration.voice" /></Field></div><VoiceDirection/><button className="button primary full-width" type="submit" data-action="narration.prepare" disabled={!!busy}>{busy === 'narration.prepare' ? <LoaderCircle size={14} className="spin" /> : <WandSparkles size={14} />}{mode === 'codex' ? '原稿と引き渡しファイルを作る' : '引き渡しファイルを作る'}</button></form>{result && <><ResultPanel result={result} title="Google Vidsに渡す原稿" /><div className="button-row"><Button icon={Copy} action="narration.copy" onClick={async () => { try { await navigator.clipboard.writeText(result.taggedScript || result.script || ''); onToast('原稿をコピーしました'); } catch { onToast('コピーできません。原稿を選択して手動でコピーしてください。', true); } }}>原稿をコピー</Button><a className="button" href={vidsUrl} target="_blank" rel="noreferrer" data-action="narration.openVids"><ExternalLink size={13} />Google Vidsを開く</a></div></>}<div className="connection-note"><Link size={14} /><div><strong>Google Vidsとの連携方法</strong><p>Vidsに原稿を貼り付け、利用可能な音声生成機能でナレーションを作ります。音声またはMP4を書き出し、ここに取り込んでください。自動操作・公開APIによる音声生成には対応していません。</p><a href={vidsUrl} target="_blank" rel="noreferrer" data-action="narration.openVids">Google Vidsを開く <ExternalLink size={11} /></a></div></div><Button icon={Upload} className="full-width" action="narration.import.open" onClick={() => onImport(null)} disabled={!!busy}>音声 / VidsのMP4を取り込む</Button><Jobs jobs={state.jobs.filter(j => j.type === 'narration')} run={run} busy={busy} narration onImport={onImport} /></>;
}

function SelectionPanel({ state, selected, run, busy, onSelect, onAdd, onConfirm, clock }) {
  const asset = selected?.type === 'asset' ? state.assets.find(a => a.id === selected.id) : null;
  const clip = selected?.type === 'clip' ? state.clips.find(c => c.id === selected.id) : null;
  const scene = selected?.type === 'scene' ? state.storyboard.find(s => s.id === selected.id) : null;
  const scenes = sortedScenes(state.storyboard);
  if (asset) return <div className="selection-form"><div className="selection-header"><span className={`selection-kind ${asset.kind}`}>{kindNames[asset.kind]}</span><span className={`decision-badge ${asset.decision}`}>{decisionNames[asset.decision]}</span></div><h3 className="selected-name">{asset.name}</h3><dl className="asset-metadata"><div><dt>長さ</dt><dd>{Number(asset.duration || 0).toFixed(3)} 秒</dd></div><div><dt>サイズ</dt><dd>{bytes(asset.size)}</dd></div>{asset.width && <div><dt>解像度</dt><dd>{asset.width} × {asset.height}</dd></div>}<div><dt>元の音声</dt><dd>{asset.hasAudio || asset.kind === 'audio' ? 'あり' : 'なし'}</dd></div></dl><form key={`${asset.id}-${asset.sceneId}`} onSubmit={async event => { event.preventDefault(); await run('asset.assign', { id: asset.id, sceneId: formObject(event.currentTarget).sceneId || null }); }}><Field label="シーンへの割り当て"><SceneSelect scenes={scenes} defaultValue={asset.sceneId || ''} /></Field><button type="submit" className="button full-width" data-action="asset.assign" data-entity-id={asset.id} disabled={!!busy}><Save size={13} />割り当てを保存</button></form><Button className="primary full-width" icon={Plus} action="timeline.add.open" entity={asset.id} onClick={() => onAdd(asset)}>タイムラインに追加</Button><hr /><form key={`${asset.id}-${asset.decision}`} onSubmit={async event => { event.preventDefault(); await run('asset.decide', { id: asset.id, ...formObject(event.currentTarget) }); }}><Field label="ショットの判断"><select name="decision" defaultValue={asset.decision} data-action="asset.decision"><option value="pending">未判定</option><option value="accepted">採用</option><option value="rejected">不採用</option></select></Field><Field label="判断の理由" hint="理由はログに残り、スキルとして書き出せます。"><textarea name="reason" rows="3" required placeholder="例：表情とテンポがシーンの意図に合う" defaultValue={[...state.decisions].reverse().find(d => d.assetId === asset.id)?.reason || ''} data-action="asset.reason" /></Field><button type="submit" className="button full-width" data-action="asset.decide" data-entity-id={asset.id} disabled={!!busy}><CheckCheck size={14} />判断を記録</button></form><hr /><div className="inspector-section-title"><Hash size={13} />素材の整合性</div><p className="muted-copy">SHA-256で原本との一致を検証します。画質の良し悪しを数値化する指標ではありません。</p><code className="hash-code">{asset.sha256}</code>{asset.streamHashes && Object.entries(asset.streamHashes).map(([kind, hash]) => <details key={kind}><summary>{kind === 'video' ? '映像' : '音声'}ストリームのハッシュ</summary><code className="hash-code">{hash}</code></details>)}<div className="button-row"><Button icon={ShieldCheck} action="asset.verify" entity={asset.id} onClick={() => run('asset.verify', { id: asset.id }, true)} disabled={!!busy}>ハッシュを検証</Button><Button icon={Trash2} className="danger-text" action="asset.remove.open" entity={asset.id} title="素材をライブラリから削除" aria-label="素材をライブラリから削除" onClick={() => onConfirm('素材を削除', 'ライブラリから素材を削除します。タイムラインで使用中の素材は削除できません。元ファイルは保持されます。', () => run('asset.remove', { id: asset.id }))} disabled={!!busy} /></div></div>;
  if (clip) { const source = state.assets.find(a => a.id === clip.assetId); return <div className="selection-form"><div className="selection-header"><span className={`selection-kind ${clip.track}`}>{clip.track === 'video' ? 'V1 · 映像' : 'A1 · 音声'}</span><span className="panel-meta">クリップ</span></div><h3 className="selected-name">{source?.name}</h3><form key={`${clip.id}-${state.updatedAt}`} onSubmit={async event => { event.preventDefault(); const data = numeric(formObject(event.currentTarget), ['start', 'in', 'duration', 'gain', ...controlKeys]); data.muted = data.muted === 'on'; if(clip.track==='video')data.keyEnabled=data.keyEnabled==='on'; data.sceneId = data.sceneId || null; await run('timeline.update', { id: clip.id, ...data }); }}><Field label="シーン"><SceneSelect scenes={scenes} defaultValue={clip.sceneId || ''} /></Field><div className="inspector-section-title">配置とトリム <span>秒</span></div><Field label="タイムライン開始"><input type="number" name="start" step="0.001" min="0" required defaultValue={clip.start} data-action="timeline.start" /></Field><div className="field-row"><Field label="ソースの開始位置"><input type="number" name="in" step="0.001" min="0" required defaultValue={clip.in} data-action="timeline.in" /></Field><Field label="クリップの長さ"><input type="number" name="duration" step="0.001" min="0.001" required defaultValue={clip.duration} data-action="timeline.duration" /></Field></div><ClipFields clip={clip}/>{clip.track === 'audio' && <Field label="音量（0〜1）"><input type="number" name="gain" min="0" max="1" step="0.05" defaultValue={clip.gain} data-action="timeline.gain" /></Field>}<label className="checkbox-field"><input type="checkbox" name="muted" defaultChecked={clip.muted} data-action="timeline.mute" />{clip.track === 'audio' ? 'この音声をミュート' : 'この映像を非表示'}</label><button className="button primary full-width" type="submit" data-action="timeline.update" data-entity-id={clip.id} disabled={!!busy}><Save size={14} />クリップを更新</button></form><div className="inline-note"><ShieldCheck size={14} />トリムしても元の素材は変更されません。</div><div className="button-row"><Button icon={Scissors} action="timeline.split" entity={clip.id} onClick={() => run('timeline.split', { id: clip.id, at: clock.time })} disabled={!!busy}>再生ヘッドで分割</Button><Button icon={Trash2} action="timeline.remove" entity={clip.id} title="クリップを削除" aria-label="クリップを削除" onClick={() => run('timeline.remove', { id: clip.id })} disabled={!!busy} /></div><hr /><Button icon={FolderOpen} className="full-width" action="asset.select" entity={source?.id} onClick={() => onSelect({ type: 'asset', id: source.id })} disabled={!source}>元の素材を表示</Button></div>; }
  if (scene) return <div className="selection-form"><div className="selection-header"><span className="selection-kind scene">シーン {String(scene.order + 1).padStart(2, '0')}</span><span className="panel-meta">ストーリーボード</span></div><form key={`${scene.id}-${state.updatedAt}`} onSubmit={async event => { event.preventDefault(); const data = new FormData(event.currentTarget); await run('storyboard.update', { id: scene.id, title: data.get('title'), description: data.get('description'), narration: data.get('narration'), duration: Number(data.get('duration')), required: data.getAll('required') }); }}><Field label="シーン名"><input name="title" required defaultValue={scene.title} data-action="storyboard.title" /></Field><Field label="予定尺（秒）"><input name="duration" type="number" step="0.1" min="0.1" required defaultValue={scene.duration} data-action="storyboard.duration" /></Field><Field label="映像・編集の意図"><textarea name="description" rows="4" defaultValue={scene.description} data-action="storyboard.description" /></Field><Field label="ナレーション原稿"><textarea name="narration" rows="4" defaultValue={scene.narration} data-action="storyboard.narration" /></Field><div className="field"><span>完成に必要なトラック</span><div className="button-row">{['video', 'audio'].map(track => <label key={track} className="checkbox-field"><input type="checkbox" name="required" value={track} defaultChecked={scene.required?.includes(track)} data-action="storyboard.required" data-entity-id={track} />{kindNames[track]}</label>)}</div></div><button className="button primary full-width" type="submit" data-action="storyboard.update" data-entity-id={scene.id} disabled={!!busy}><Save size={14} />シーンを保存</button></form><p className="muted-copy">完成度は、シーンの予定区間を覆うクリップの秒数で計算します。尺・順序を変えた後は配置も確認してください。</p><Button icon={Trash2} className="danger-text full-width" action="storyboard.remove.open" entity={scene.id} onClick={() => onConfirm('シーンを削除', `「${scene.title}」をストーリーボードから削除します。`, () => run('storyboard.remove', { id: scene.id }))} disabled={!!busy}>シーンを削除</Button></div>;
  return <div className="project-details"><h3>プロジェクト</h3><dl className="asset-metadata"><div><dt>名前</dt><dd>{state.name}</dd></div><div><dt>解像度</dt><dd>{state.width} × {state.height}</dd></div><div><dt>フレームレート</dt><dd>{state.fps} fps</dd></div><div><dt>長さ</dt><dd>{timecode(timelineDuration(state), state.fps)}</dd></div><div><dt>素材</dt><dd>{state.assets.length}</dd></div><div><dt>クリップ</dt><dd>{state.clips.length}</dd></div></dl><p className="muted-copy">素材またはクリップを選択すると、詳細を編集できます。</p></div>;
}

export default function App() {
  const [connectHere,setConnectHere]=useState(!isHosted);
  return connectHere?<Editor/>:<Startup onConnect={()=>setConnectHere(true)}/>;
}

function Editor() {
  const [projectChosen,setProjectChosen]=useState(false);
  const [loadAttempt,setLoadAttempt]=useState(0);
  const [state, setState] = useState(null), [loadError, setLoadError] = useState(''), [connected, setConnected] = useState(false);
  const [selected, setSelected] = useState(null), [sourceId, setSourceId] = useState(null), [tab, setTab] = useState('inspect');
  const [showStoryboard, setShowStoryboard] = useState(false);
  const [overlayMode, setOverlayMode] = useState('graphic');
  const [modal, setModal] = useState(null), [busy, setBusy] = useState(''), [toast, setToast] = useState(null), [result, setResult] = useState(null);
  const [capabilities, setCapabilities] = useState(null), [commandSearch, setCommandSearch] = useState('');
  const [paletteCommand, setPaletteCommand] = useState(''), [paletteArgs, setPaletteArgs] = useState('{}');
  const uploadRef = useRef(null), narrationUploadRef = useRef(null), importContext = useRef(null), toastTimeout = useRef(null);
  const clock = useMemo(createClock, []);
  clock.duration = state ? timelineDuration(state) : 0;
  const notify = useCallback((message, error = false) => { clearTimeout(toastTimeout.current); setToast({ message, error }); toastTimeout.current = setTimeout(() => setToast(null), error ? 10000 : 4500); }, []);
  const closeModal = useCallback(() => { setModal(null); setResult(null); }, []);
  const run = useCallback(async (command, args = {}, showResult = false) => {
    if(!projectChosen&&!/^project\.(list|new|switch|open)$/.test(command)){notify('プロジェクトを選択してください',true);return null;}
    setBusy(command);
    try { const response = await request('/api/command', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ command, args }) }); if (response.state) setState(response.state); if (/^project\.(new|switch|open)$/.test(command)) setProjectChosen(true); if (showResult) { setModal({ type: 'result', title: '実行結果' }); setResult(response.result); } else if (!['generation.refresh'].includes(command)) notify('保存しました'); return response; }
    catch (error) { notify(error.message, true); return null; }
    finally { setBusy(''); }
  }, [notify,projectChosen]);
  useEditorTools({state:projectChosen?state:null,run,capabilities,clock,onProjectChange:()=>{setSelected(null);setSourceId(null);clock.pause();clock.seek(0);}});

  useEffect(() => {
    let alive = true, loading = false, gotCapabilities = false, retry;
    let loadSucceeded=false;
    const load = async () => { if(loading)return;loading=true;loadSucceeded=false;try { const next = await request('/api/state', {signal:AbortSignal.timeout(5000)}); if (alive) { setState(previous=>previous?.id===next.id&&previous?.updatedAt===next.updatedAt?previous:next); setConnected(true); setLoadError(''); loadSucceeded=true; } if(!gotCapabilities){const value=await request('/api/capabilities');if(alive){setCapabilities(value);gotCapabilities=true;}} } catch (error) { if (alive) { setLoadError(error.message); setConnected(false); } } finally{loading=false;if(alive)retry=setTimeout(load,loadSucceeded?(isHosted?5000:15000):2000);} };
    load();
    const events = isHosted ? {} : new EventSource('/api/events');
    events.onopen = () => { if (alive) setConnected(true); };
    events.onmessage = event => { try { const next = JSON.parse(event.data); if (alive && next.id && Array.isArray(next.clips)) { setState(next); setConnected(true); } } catch { /* Ignore keep-alive payloads. */ } };
    events.onerror = () => { if (alive) setConnected(false); };
    return () => { alive = false; events.close?.(); clearTimeout(retry); clearTimeout(toastTimeout.current); };
  }, [loadAttempt]);

  useEffect(() => { if (state) { if (clock.time > clock.duration) clock.seek(clock.duration); clock.notify(); } }, [state, clock]);
  useEffect(() => {
    const handler = event => {
      if(!projectChosen)return;
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); setModal({ type: 'commands' }); return; }
      if (event.target.closest('input, textarea, select, [contenteditable="true"]') || modal) return;
      if ((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();run(event.shiftKey?'edit.redo':'edit.undo');return;}
      if (event.code === 'Space') { event.preventDefault(); setSourceId(null); clock.toggle(); }
      if (event.key.toLowerCase() === 's' && selected?.type === 'clip' && !busy) { event.preventDefault(); run('timeline.split', { id: selected.id, at: clock.time }); }
      if ((event.key === 'Delete' || event.key === 'Backspace') && ['caption', 'graphic'].includes(selected?.type) && !busy) { event.preventDefault(); run(`${selected.type === 'caption' ? 'caption' : 'graphics'}.remove`, { id: selected.id }); }
      if ((event.key === 'Delete' || event.key === 'Backspace') && selected?.type === 'clip' && !busy) { event.preventDefault(); run('timeline.remove', { id: selected.id }); }
    };
    window.addEventListener('keydown', handler); return () => window.removeEventListener('keydown', handler);
  }, [clock, selected, run, modal, busy, projectChosen]);

  const upload = async (files, narration = false) => {
    if (!files?.length) return;
    const data = new FormData(); Array.from(files).forEach(file => data.append('files', file));
    const sceneId = narration ? importContext.current?.sceneId : selected?.type === 'scene' ? selected.id : null;
    if (sceneId) data.append('sceneId', sceneId);
    if (narration) { data.append('narration', 'true'); if (importContext.current?.jobId) data.append('jobId', importContext.current.jobId); }
    setBusy(narration ? 'narration.import' : 'asset.upload');
    try { const response = await request('/api/upload', { method: 'POST', body: data }); setState(response.state); const asset = response.result?.[0]; if (asset) { setSelected({ type: 'asset', id: asset.id }); setTab('inspect'); } notify(`${response.result?.length || files.length} 件の素材を取り込みました`); }
    catch (error) { notify(error.message, true); } finally { setBusy(''); if (uploadRef.current) uploadRef.current.value = ''; if (narrationUploadRef.current) narrationUploadRef.current.value = ''; }
  };
  const onNarrationImport = job => { importContext.current = { jobId: job?.id, sceneId: job?.sceneId || (selected?.type === 'scene' ? selected.id : null) }; narrationUploadRef.current.click(); };
  const confirm = (title, description, action) => setModal({ type: 'confirm', title, description, action });
  const selectAsset = asset => { clock.pause(); setSelected({ type: 'asset', id: asset.id }); setSourceId(asset.id); setTab('inspect'); };
  const selectClip = clip => { setSelected({ type: 'clip', id: clip.id }); setSourceId(null); setTab('inspect'); };
  const selectOverlay = value => { setSelected(value); if (value?.type) setOverlayMode(value.type); setTab('overlays'); setSourceId(null); };
  const addAsset = asset => setModal({ type: 'addClip', asset });
  const progress = useMemo(() => state ? coverage(state) : null, [state]);
  const scenes = useMemo(() => state ? sortedScenes(state.storyboard) : [], [state?.storyboard]);
  const selectedScene = selected?.type === 'scene' ? selected.id : selected?.type === 'asset' ? state?.assets.find(a => a.id === selected.id)?.sceneId : selected?.type === 'clip' ? state?.clips.find(c => c.id === selected.id)?.sceneId : null;

  if (!state) return loadError?<Startup waiting detail={loadError} onConnect={()=>setLoadAttempt(n=>n+1)}/>:<main className="boot-screen"><div className="brand-mark"><Scissors size={22}/></div><h1>Cutton</h1><LoaderCircle size={20} className="spin"/><p>プロジェクトを読み込んでいます</p></main>;

  if(!projectChosen)return <ProjectLauncher run={run} busy={busy} error={toast?.error?toast.message:loadError}/>;

  return <main className="studio" onDragOver={event => { if (event.dataTransfer.types.includes('Files')) event.preventDefault(); }} onDrop={event => { if (event.dataTransfer.files.length) { event.preventDefault(); if (!busy) upload(event.dataTransfer.files); } }}>
    <input ref={uploadRef} className="visually-hidden" type="file" multiple accept="video/*,audio/*,image/*,.mkv,.mov,.wav,.flac" aria-label="読み込む素材ファイル" data-action="asset.upload.files" onChange={event => upload(event.target.files)} />
    <input ref={narrationUploadRef} className="visually-hidden" type="file" accept="audio/*,video/mp4,.mov,.mkv,.wav,.flac" aria-label="ナレーション音声またはVidsのMP4" data-action="narration.import.files" onChange={event => upload(event.target.files, true)} />
    <header className="app-header"><div className="brand"><span className="brand-mark"><Scissors size={17} /></span><span>Cutton</span></div><span className="header-divider" /><button className="project-title" data-action="project.menu" onClick={() => setModal({ type: 'project' })}><span>{state.name}</span><ChevronDown size={13} /></button><span className="saved-status"><span className={`status-dot ${connected ? '' : 'offline'}`} />{busy ? '処理中…' : connected ? 'ローカル保存' : '再接続中'}</span><div className="header-spacer" /><Button icon={Terminal} className="command-open" action="commands.open" aria-label="コマンド (Ctrl K)" title="コマンド (Ctrl K)" onClick={() => setModal({ type: 'commands' })} /><Button icon={Settings2} title="接続と設定" aria-label="接続と設定" action="settings.open" onClick={() => setModal({ type: 'settings' })} /><Button icon={ArrowDownToLine} className="export-button" action="export.open" onClick={() => setModal({ type: 'export' })}>書き出し</Button></header>
    <div className="workspace-bar"><div className="workspace-functions"><Button icon={FolderOpen} action="asset.upload.open" onClick={() => uploadRef.current.click()} disabled={!!busy}>メディア</Button><Button icon={Music2} action="narration.open" onClick={() => setTab('narration')} className={tab === 'narration' ? 'active' : ''}>オーディオ</Button><Button icon={Music2} action="mixer.open" onClick={()=>setTab('mixer')} className={tab==='mixer'?'active':''}>ミキサー</Button><Button icon={Music2} action="sfx.open" onClick={()=>setTab('sfx')} className={tab==='sfx'?'active':''}>効果音</Button><Button icon={Sparkles} action="generation.open" onClick={() => setTab('generate')} className={tab === 'generate' ? 'active' : ''}>AI生成</Button><Button icon={Captions} action="captions.open" onClick={() => { setOverlayMode('caption'); setTab('overlays'); }} className={tab === 'overlays' && overlayMode === 'caption' ? 'active' : ''}>字幕</Button><Button icon={Type} action="graphics.open" onClick={() => { setOverlayMode('graphic'); setTab('overlays'); }} className={tab === 'overlays' && overlayMode === 'graphic' ? 'active' : ''}>グラフィック</Button></div><div><Button icon={Layers3} action="storyboard.toggle" aria-pressed={showStoryboard} className={showStoryboard ? 'active' : ''} onClick={() => setShowStoryboard(value => !value)}>ストーリーボード{scenes.length > 0 && <span className="completion-value">{progress.percent}%</span>}</Button><Button icon={WandSparkles} className="plan-button" action="plan.open" onClick={() => setModal({ type: 'plan' })}>編集プラン</Button></div></div>
    <div className="workbench"><Library assets={state.assets} scenes={scenes} selected={selected} onSelect={selectAsset} onUpload={() => uploadRef.current.click()} onAdd={addAsset} onGenerate={() => setTab('generate')} busy={!!busy} /><div className="center-column"><Player state={state} clock={clock} selected={selected} onOverlaySelect={v=>v.type==='clip'?selectClip(state.clips.find(c=>c.id===v.id)):selectOverlay(v)} onTransform={(kind,id,fields)=>run(`${kind==='clip'?'timeline':kind==='graphic'?'graphics':'caption'}.update`,{id,...fields})} busy={!!busy} selectedAsset={state.assets.find(a => a.id === sourceId)} sourceCandidate={selected?.type === 'asset' ? state.assets.find(a => a.id === selected.id) : selected?.type === 'clip' ? state.assets.find(a => a.id === state.clips.find(c => c.id === selected.id)?.assetId) : null} onSelectSource={asset => { clock.pause(); setSourceId(asset.id); }} onClearAsset={() => setSourceId(null)} />{showStoryboard && <Storyboard progress={progress} selected={selected} onSelect={scene => { setSelected({ type: 'scene', id: scene.id }); setSourceId(null); setTab('inspect'); clock.seek(scene.start); }} onAdd={() => setModal({ type: 'addScene' })} onPlan={() => setModal({ type: 'plan' })} onReorder={(index, direction) => { const ids = scenes.map(scene => scene.id); [ids[index], ids[index + direction]] = [ids[index + direction], ids[index]]; run('storyboard.reorder', { ids }); }} />}</div><aside className="inspector"><div className="inspector-tabs" role="tablist" aria-label="インスペクター">{[['inspect', Settings2, '詳細'], ['generate', Sparkles, '生成'], ['narration', Mic, '音声'], ['overlays', Type, 'テキスト'], ['mixer', Music2, 'ミックス'], ['sfx', Music2, '効果音']].map(([id, Icon, label]) => <button key={id} role="tab" aria-selected={tab === id} aria-controls={`panel-${id}`} className={tab === id ? 'active' : ''} data-action="inspector.tab" data-entity-id={id} onClick={() => setTab(id)}><Icon size={14} />{label}</button>)}</div><div className="inspector-content" role="tabpanel" id={`panel-${tab}`}>{tab==='mixer'?<MixerPanel state={state} run={run} busy={!!busy}/>:tab==='sfx'?<SoundPanel clock={clock} run={run} busy={!!busy}/>:tab === 'overlays' ? <OverlayEditor state={state} selected={selected} mode={overlayMode} onMode={setOverlayMode} onSelect={selectOverlay} clock={clock} run={run} busy={busy} /> : tab === 'inspect' ? <SelectionPanel state={state} selected={selected} run={run} busy={busy} onSelect={setSelected} onAdd={addAsset} onConfirm={confirm} clock={clock} /> : tab === 'generate' ? <GenerationPanel state={state} run={run} busy={busy} selectedScene={selectedScene} /> : <NarrationPanel state={state} run={run} busy={busy} selectedScene={selectedScene} onImport={onNarrationImport} onToast={notify} />}</div></aside></div>
    <EditTools state={state} clock={clock} selected={selected} run={run} busy={!!busy}/>
    <Timeline state={state} clock={clock} onOverlaySelect={selectOverlay} onOverlayUpdate={(kind, id, fields) => run(`${kind === 'caption' ? 'caption' : 'graphics'}.update`, { id, ...fields })} onOverlayDelete={(kind, id) => run(`${kind === 'caption' ? 'caption' : 'graphics'}.remove`, { id })} selected={selected} onSelect={selectClip} onUpdate={(id, fields) => run('timeline.update', { id, ...fields })} onSplit={clip => run('timeline.split', { id: clip.id, at: clock.time })} onDelete={clip => run('timeline.remove', { id: clip.id })} onArrange={() => confirm('採用素材をシーン順に整列', '現在のタイムラインを組み直します。各シーンの採用素材から、映像と音声を1本ずつ配置します。', () => run('timeline.arrange'))} onClear={() => confirm('タイムラインを空にする', 'すべてのクリップ配置を削除します。素材とストーリーボードは残ります。', () => run('timeline.clear'))} busy={!!busy} />
    {busy && <div className="busy-bar" role="status"><LoaderCircle className="spin" size={14} />{busy === 'plan.create' ? '編集プランを作成しています…' : busy === 'narration.prepare' ? 'ナレーション原稿を準備しています…' : busy === 'export.create' ? 'ファイルを書き出しています…' : busy.includes('upload') || busy.includes('import') ? '素材を取り込み、ハッシュを計算しています…' : '処理しています…'}</div>}
    {toast && <div className={`toast ${toast.error ? 'error' : ''}`} role={toast.error ? 'alert' : 'status'}>{toast.error ? <X size={16} /> : <Check size={16} />}<span>{toast.message}</span><Button icon={X} action="toast.dismiss" title="通知を閉じる" aria-label="通知を閉じる" onClick={() => setToast(null)} /></div>}
    {modal && <Modal title={modal.title || ({ plan: '編集プラン', addScene: 'シーンを追加', addClip: 'タイムラインに追加', settings: '接続と設定', project: 'プロジェクト', export: '書き出しと引き継ぎ', commands: 'コマンドセンター', newProject: '新規プロジェクト', openProject: 'プロジェクトを開く' }[modal.type] || '実行結果')} onClose={closeModal} wide={['export', 'commands', 'plan'].includes(modal.type)}>
      {modal.type === 'plan' && <form className="modal-body" onSubmit={async event => { event.preventDefault(); const data = numeric(formObject(event.currentTarget), ['duration']); const response = await run('plan.create', data); if (response) { setSourceId(null); setSelected(null); clock.seek(0); closeModal(); } }}><p className="modal-lead">動画の内容からシーン・尺・ナレーションを作成します。</p><Field label="どんな動画を作りますか？"><textarea name="prompt" rows="5" required autoFocus data-action="plan.prompt" placeholder="例：高校生に英語学習の楽しさを伝える30秒の動画。教室の導入から、学びの変化、最後のメッセージへ。テンポよく、温かい印象で。" /></Field><div className="field-row"><Field label="全体の予定尺（秒）"><input name="duration" type="number" min="1" max="3600" defaultValue="30" required data-action="plan.duration" /></Field><Field label="プランの作成方法"><select name="mode" defaultValue="codex" data-action="plan.mode"><option value="codex">Codex App Serverで生成</option><option value="local">ローカルの定型構成を作成</option></select></Field></div><div className="connection-note"><Terminal size={17} /><div><strong>Codex App Server</strong><p>この操作を実行するとCodexが起動します。ローカル構成はAIを使用しない定型のたたき台です。{scenes.length > 0 && '既存のストーリーボードは置き換わります。'}</p></div></div>{state.clips.length > 0 && <p className="inline-error">タイムラインにクリップがあります。プランを作り直す場合は先にタイムラインを空にするか、新規プロジェクトを作成してください。</p>}<div className="modal-actions"><Button action="dialog.close" onClick={closeModal}>キャンセル</Button><button className="button primary" type="submit" data-action="plan.create" disabled={!!busy || state.clips.length > 0}><Sparkles size={14} />構成を作成</button></div></form>}
      {modal.type === 'addScene' && <form className="modal-body" onSubmit={async event => { event.preventDefault(); const form = new FormData(event.currentTarget); const response = await run('storyboard.add', { title: form.get('title'), description: form.get('description'), narration: form.get('narration'), duration: Number(form.get('duration')), required: form.getAll('required') }); if (response) closeModal(); }}><Field label="シーン名"><input name="title" required autoFocus placeholder="導入：ストーリーの始まり" data-action="storyboard.title" /></Field><Field label="予定尺（秒）"><input name="duration" type="number" step="0.1" min="0.1" defaultValue="5" required data-action="storyboard.duration" /></Field><Field label="映像・編集の意図"><textarea name="description" rows="3" data-action="storyboard.description" placeholder="どんな映像を、どうつなぐか" /></Field><Field label="ナレーション原稿"><textarea name="narration" rows="3" data-action="storyboard.narration" /></Field><div className="field"><span>必要なトラック</span><div className="button-row"><label className="checkbox-field"><input name="required" type="checkbox" value="video" defaultChecked data-action="storyboard.requiredVideo" />映像</label><label className="checkbox-field"><input name="required" type="checkbox" value="audio" defaultChecked data-action="storyboard.requiredAudio" />音声</label></div></div><div className="modal-actions"><Button action="dialog.close" onClick={closeModal}>キャンセル</Button><button className="button primary" type="submit" data-action="storyboard.add" disabled={!!busy}><Plus size={14} />シーンを追加</button></div></form>}
      {modal.type === 'addClip' && <form className="modal-body" onSubmit={async event => { event.preventDefault(); const data = numeric(formObject(event.currentTarget), ['start', 'in', 'duration']); const response = await run('timeline.add', { ...data, assetId: modal.asset.id, sceneId: data.sceneId || null }); if (response) { setSourceId(null); closeModal(); } }}><div className="import-asset-label"><Film size={19} /><strong>{modal.asset.name}</strong></div><Field label="シーン"><SceneSelect scenes={scenes} defaultValue={modal.asset.sceneId || selectedScene || ''} /></Field><Field label="トラック"><select name="track" defaultValue={modal.asset.kind === 'audio' ? 'audio' : 'video'} data-action="timeline.track">{modal.asset.kind !== 'audio' && <option value="video">V1 · 映像（元の音声はミュート）</option>}{(modal.asset.kind === 'audio' || modal.asset.hasAudio) && <option value="audio">A1 · 音声のみ</option>}</select></Field><div className="field-row"><Field label="配置開始（秒）"><input name="start" type="number" step="0.001" min="0" defaultValue={Math.round(clock.time * 1000) / 1000} required data-action="timeline.start" /></Field><Field label="ソース開始（秒）"><input name="in" type="number" step="0.001" min="0" defaultValue="0" required data-action="timeline.in" /></Field><Field label="長さ（秒）"><input name="duration" type="number" step="0.001" min="0.001" defaultValue={modal.asset.kind === 'image' ? 5 : Number((modal.asset.duration || 5).toFixed(3))} required data-action="timeline.duration" /></Field></div><p className="muted-copy">同じトラックのクリップとは重ねて配置できません。空いている開始位置を指定してください。</p><div className="modal-actions"><Button action="dialog.close" onClick={closeModal}>キャンセル</Button><button className="button primary" type="submit" data-action="timeline.add" disabled={!!busy}><Plus size={14} />追加</button></div></form>}
      {modal.type === 'settings' && <div className="modal-body"><form onSubmit={async event => { event.preventDefault(); const response = await run('settings.update', formObject(event.currentTarget)); if (response) notify('接続設定を保存しました'); }}><Field label="ComfyUI URL"><input name="comfyUrl" type="url" defaultValue={state.settings.comfyUrl} placeholder="http://127.0.0.1:8188" required data-action="settings.comfyUrl" /></Field><Field label="Google Vids プロジェクトURL" hint="空欄の場合はGoogle Vidsホームを開きます。"><input name="vidsUrl" type="url" defaultValue={state.settings.vidsUrl} placeholder="https://docs.google.com/videos/…" data-action="settings.vidsUrl" /></Field><Field label="Codex モデル" hint="空欄の場合はCodexで設定済みのモデルを使用します。"><input name="codexModel" defaultValue={state.settings.codexModel} placeholder="設定済みのモデルを使用" data-action="settings.codexModel" /></Field><div className="button-row"><button className="button primary" type="submit" data-action="settings.update" disabled={!!busy}><Save size={14} />設定を保存</button><Button icon={RefreshCw} action="integrations.check" disabled={!!busy} onClick={async () => { const response = await run('integrations.check'); if (response) setResult(response.result); }}>接続を確認</Button></div></form><ResultPanel result={result} title="接続状況" /><div className="connection-note"><ShieldCheck size={16} /><div><strong>このPCに合わせて処理</strong>{capabilities?.performance&&<p>{capabilities.performance.cpu} · {capabilities.performance.memoryGiB} GiB<br/>書き出し {capabilities.performance.encodeThreads} スレッド / 同時書き出し 1 本。設定した解像度・fpsを保持します。</p>}<p>元のメディアを参照して再生し、映像と音声を分けて保持します。動画の全フレーム展開や自動生成は行いません。生成サービスへの接続は操作時に行います。</p></div></div></div>}
      {modal.type === 'project' && <div className="modal-body"><ProjectBrowser state={state} run={run} onOpen={() => {setSelected(null);setSourceId(null);clock.seek(0);closeModal();}} /><hr /><form onSubmit={async event => { event.preventDefault(); const response = await run('project.rename', formObject(event.currentTarget)); if (response) closeModal(); }}><Field label="プロジェクト名"><input name="name" defaultValue={state.name} required autoFocus data-action="project.name" /></Field><button className="button primary full-width" type="submit" data-action="project.rename" disabled={!!busy}><Save size={14} />名前を保存</button></form><hr /><Button icon={Plus} className="full-width" action="project.new.open" onClick={() => setModal({ type: 'newProject' })}>新規プロジェクト</Button><Button icon={FolderOpen} className="full-width" action="project.open.open" onClick={() => setModal({ type: 'openProject' })}>保存済みプロジェクトを開く</Button><div className="project-facts"><span>{scenes.length} シーン</span><span>{state.assets.length} 素材</span><span>{state.clips.length} クリップ</span></div></div>}
      {modal.type === 'newProject' && <form className="modal-body" onSubmit={async event => { event.preventDefault(); const response = await run('project.new', formObject(event.currentTarget)); if (response) { setSelected(null); setSourceId(null); clock.pause(); clock.seek(0); closeModal(); } }}><p className="modal-lead">現在のプロジェクトをアーカイブして、新しい編集を始めます。</p><Field label="新しいプロジェクト名"><input name="name" required autoFocus placeholder="新しいストーリー" data-action="project.name" /></Field><div className="modal-actions"><Button action="dialog.close" onClick={closeModal}>キャンセル</Button><button className="button primary" type="submit" data-action="project.new" disabled={!!busy}><Plus size={14} />新規作成</button></div></form>}
      {modal.type === 'openProject' && <form className="modal-body" onSubmit={async event => { event.preventDefault(); const response = await run('project.open', formObject(event.currentTarget)); if (response) { setSelected(null); setSourceId(null); clock.pause(); clock.seek(0); closeModal(); } }}><p className="modal-lead">書き出したCuttonプロジェクトJSON、またはアーカイブのJSONを開きます。</p><Field label="プロジェクトJSONの絶対パス"><input name="path" required autoFocus placeholder="C:\…\project.json" data-action="project.open.path" /></Field><div className="modal-actions"><Button action="dialog.close" onClick={closeModal}>キャンセル</Button><button className="button primary" type="submit" data-action="project.open" disabled={!!busy}><FolderOpen size={14} />開く</button></div></form>}
      {modal.type === 'confirm' && <div className="modal-body"><p className="modal-lead">{modal.description}</p><div className="modal-actions"><Button action="dialog.close" onClick={closeModal}>キャンセル</Button><Button className="primary" action="confirmation.execute" onClick={async () => { const response = await modal.action(); if (response) closeModal(); }} disabled={!!busy}>実行</Button></div></div>}
      {modal.type === 'export' && <div className="modal-body"><p className="modal-lead">形式を選んで書き出します。</p><div className="export-grid">{[['bundle', FolderOpen, 'プロジェクト一式', '元素材・プロジェクトJSON・交換用タイムラインをZIPにまとめます。', 'ZIP'], ['render', Film, '動画として書き出し', '映像と音声を合成したMP4。再エンコードが発生します。', 'MP4'], ['otio', Layers3, 'OpenTimelineIO', 'OTIO対応アプリへ。素材の再リンクが必要な場合があります。', 'OTIO'], ['fcpmodern', FileJson, 'Final Cut Pro', 'FCPXML 1.10。複数レーン・速度・基本変形を引き継ぎます。', 'FCPXML'], ['fcpxml', FileJson, 'Premiere / Resolve XML', 'FCP 7形式のXML。基本的なカットとトラックを引き継ぎます。', 'XML'], ['edl', Scissors, '編集点リスト', 'シンプルなカットの交換用。音声・効果の表現には制限があります。', 'EDL'], ['clips', ArrowDownToLine, '個別素材と編集情報', '原本素材と編集位置をZIPへ。CapCutなどへ素材を持ち込みます。', 'ZIP']].map(([format, Icon, title, description, badge]) => <button className="export-card" key={format} data-action="export.create" data-entity-id={format} disabled={!!busy} onClick={async () => { const response = await run('export.create', { format }); if (response) setResult(response.result); }}><div><Icon size={21} /><span>{badge}</span></div><strong>{title}</strong><p>{description}</p></button>)}</div><p className="muted-copy">アプリによって対応形式が異なります。CapCutの専用プロジェクト形式は生成しません。元素材のハッシュ一致と、完成動画の再エンコードは別に扱います。</p><ResultPanel result={result} title="書き出しが完了しました" /><hr /><div className="export-decisions"><div><strong>採用・不採用ログ</strong><p>{state.decisions.length} 件の採用・不採用ログをスキルに書き出せます。</p></div><Button icon={ArrowDownToLine} action="decisions.export" disabled={!!busy || !state.decisions.length} onClick={async () => { const response = await run('decisions.export'); if (response) setResult(response.result); }}>判断スキルを書き出し</Button></div></div>}
      {modal.type === 'commands' && <div className="modal-body command-modal"><p className="muted-copy">GUIと同じ操作をCLI・MCPから実行できます。ここではコマンドと引数を確認して実行します。</p><label className="search-field"><Command size={15} /><input autoFocus aria-label="コマンドを検索" placeholder="コマンドを検索…" value={commandSearch} onChange={event => setCommandSearch(event.target.value)} data-action="commands.search" /></label><div className="command-browser"><div className="command-list">{(capabilities?.commands || []).filter(c => `${c.name} ${c.description}`.toLowerCase().includes(commandSearch.toLowerCase())).map(command => <button key={command.name} className={paletteCommand === command.name ? 'active' : ''} data-action="commands.select" data-entity-id={command.name} onClick={() => { setPaletteCommand(command.name); setPaletteArgs('{}'); }}><code>{command.name}</code><span>{command.description}</span></button>)}</div><form onSubmit={async event => { event.preventDefault(); let args; try { args = JSON.parse(paletteArgs); } catch { notify('引数JSONを確認してください。', true); return; } const response = await run(paletteCommand, args); if (response) setResult(response.result); }}><Field label="コマンド"><input value={paletteCommand} onChange={event => setPaletteCommand(event.target.value)} required data-action="commands.name" placeholder="timeline.add" /></Field><Field label="引数（JSON）"><textarea className="code-input" rows="10" value={paletteArgs} onChange={event => setPaletteArgs(event.target.value)} data-action="commands.args" /></Field><button type="submit" className="button primary full-width" data-action="commands.execute" disabled={!!busy || !paletteCommand}><Terminal size={14} />コマンドを実行</button>{capabilities?.commands.find(c => c.name === paletteCommand)?.args && <pre className="command-schema">{JSON.stringify(capabilities.commands.find(c => c.name === paletteCommand).args, null, 2)}</pre>}</form></div><ResultPanel result={result} /></div>}
      {modal.type === 'result' && <div className="modal-body"><ResultPanel result={result} /></div>}
    </Modal>}
  </main>;
}
